	allegiance = "Los Atal'ai",
	sections = {
		{
			title = "Resumen",
			text = [=[Atal'alarion es el guardián del ídolo que yace en el fondo del templo ahogado. En torno a una sala redonda hay seis balcones, cada uno con una estatua de serpiente en su borde. En la base de la sala aguarda un altar de {link:hakkar}Hakkar{/link}. Quienes despiertan las estatuas de forma equivocada caen víctimas de trampas. Quienes hallan el orden correcto hacen surgir al guardián. Es un bruto enorme, y promete darse un festín con los huesos de los intrusos.]=],
		},
		{
			title = "Importancia",
			text = [=[Atal'alarion guarda el tesoro de los Atal'ai. El erudito goblin {link:marvon-rivetseeker}Marvon Rivetseeker{/link} fue el primer forastero en hallar el círculo, y casi le costó la vida.]=],
		},
	},
	chapters = {
		{
			title = "El secreto del círculo",
			hint = "Ayude al erudito goblin de Tanaris a desvelar el altar.",
			text = [=[{link:marvon-rivetseeker}Marvon{/link} colocó una ficha de piedra en el altar de {link:hakkar}Hakkar{/link}, y de ella despertó una secuencia de luces. Cuando se tocaron las estatuas en el orden que revelaron las luces, el guardián se alzó. Tras el ojo del ídolo yacía el tesoro de los Atal'ai.]=],
		},
	},
	mentions = {
		{ text = "Hacia las profundidades" },
		{ text = "Un ingrediente mejor" },
	},
	bonds = {
		{ id = "hakkar", name = "Hakkar", note = "el dios cuyo altar custodia" },
	},
})

